    #[test]
    fn permission_actions_require_focused_submitter_authority() {
        let pending = vec![PendingPermission {
            permission_id: "permission-a".into(),
            session_id: "session-a".into(),
            tool: "bash".into(),
            reason: "run check".into(),
            args_summary: String::new(),
