  1	//! Locally reactive, bounded plots driven by declarative math expressions.
  2	
  3	use std::collections::{BTreeMap, BTreeSet};
  4	
  5	use leptos::prelude::*;
  6	use serde_json::{json, Value};
  7	
  8	use crate::daemon::Daemon;
  9	
 10	const MAX_PARAMETERS: usize = 12;
 11	const MAX_SERIES: usize = 6;
 12	const MAX_METRICS: usize = 12;
 13	const MAX_SAMPLES: usize = 512;
 14	const MAX_EXPRESSION_LEN: usize = 512;
 15	
 16	#[derive(Clone, Debug)]
 17	struct PlotConfig {
 18	    title: String,
 19	    description: String,
 20	    parameters: Vec<Parameter>,
 21	    x: Axis,
 22	    y_label: String,
 23	    series: Vec<Series>,
 24	    metrics: Vec<Metric>,
 25	}
 26	
 27	#[derive(Clone, Debug)]
 28	struct Parameter {
 29	    id: String,
 30	    label: String,
 31	    min: f64,
 32	    max: f64,
 33	    step: f64,
 34	    value: f64,
 35	    unit: String,
 36	}
 37	
 38	#[derive(Clone, Debug)]
 39	struct Axis {
 40	    id: String,
 41	    label: String,
 42	    min: f64,
 43	    max: f64,
 44	    samples: usize,
 45	}
 46	
 47	#[derive(Clone, Debug)]
 48	struct Series {
 49	    label: String,
 50	    expression: Expr,
 51	}
 52	
 53	#[derive(Clone, Debug)]
 54	struct Metric {
 55	    label: String,
 56	    expression: Expr,
 57	    unit: String,
 58	    precision: usize,
 59	}
 60	
 61	#[derive(Clone, Debug, PartialEq)]
 62	enum Expr {
 63	    Number(f64),
 64	    Variable(String),
 65	    Unary(char, Box<Expr>),
 66	    Binary(char, Box<Expr>, Box<Expr>),
 67	    Function(String, Vec<Expr>),
 68	}
 69	
 70	struct Parser<'a> {
 71	    source: &'a str,
 72	    offset: usize,
 73	}
 74	
 75	impl<'a> Parser<'a> {
 76	    fn parse(source: &'a str) -> Result<Expr, String> {
 77	        if source.trim().is_empty() {
 78	            return Err("expression is empty".into());
 79	        }
 80	        if source.len() > MAX_EXPRESSION_LEN {
 81	            return Err(format!(
 82	                "expression exceeds {MAX_EXPRESSION_LEN} characters"
 83	            ));
 84	        }
 85	        let mut parser = Self { source, offset: 0 };
 86	        let expression = parser.parse_additive()?;
 87	        parser.skip_space();
 88	        if parser.offset != source.len() {
 89	            return Err(format!(
 90	                "unexpected input at character {}",
 91	                parser.offset + 1
 92	            ));
 93	        }
 94	        Ok(expression)
 95	    }
 96	
 97	    fn parse_additive(&mut self) -> Result<Expr, String> {
 98	        let mut left = self.parse_multiplicative()?;
 99	        loop {
100	            self.skip_space();
101	            let Some(operator @ ('+' | '-')) = self.peek() else {
102	                return Ok(left);
103	            };
104	            self.bump();
105	            left = Expr::Binary(
106	                operator,
107	                Box::new(left),
108	                Box::new(self.parse_multiplicative()?),
109	            );
110	        }
111	    }
112	
113	    fn parse_multiplicative(&mut self) -> Result<Expr, String> {
114	        let mut left = self.parse_unary()?;
115	        loop {
116	            self.skip_space();
117	            let Some(operator @ ('*' | '/')) = self.peek() else {
118	                return Ok(left);
119	            };
120	            self.bump();
121	            left = Expr::Binary(operator, Box::new(left), Box::new(self.parse_unary()?));
122	        }
123	    }
124	
125	    fn parse_unary(&mut self) -> Result<Expr, String> {
126	        self.skip_space();
127	        if let Some(operator @ ('+' | '-')) = self.peek() {
128	            self.bump();
129	            return Ok(Expr::Unary(operator, Box::new(self.parse_unary()?)));
130	        }
131	        self.parse_power()
132	    }
133	
134	    fn parse_power(&mut self) -> Result<Expr, String> {
135	        let left = self.parse_primary()?;
136	        self.skip_space();
137	        if self.peek() == Some('^') {
138	            self.bump();
139	            return Ok(Expr::Binary(
140	                '^',
141	                Box::new(left),
142	                Box::new(self.parse_unary()?),
143	            ));
144	        }
145	        Ok(left)
146	    }
147	
148	    fn parse_primary(&mut self) -> Result<Expr, String> {
149	        self.skip_space();
150	        match self.peek() {
151	            Some('(') => {
152	                self.bump();
153	                let expression = self.parse_additive()?;
154	                self.skip_space();
155	                if self.bump() != Some(')') {
156	                    return Err("missing closing parenthesis".into());
157	                }
158	                Ok(expression)
159	            }
160	            Some(ch) if ch.is_ascii_digit() || ch == '.' => self.parse_number(),
161	            Some(ch) if is_identifier_start(ch) => self.parse_name(),
162	            Some(ch) => Err(format!(
163	                "unexpected '{ch}' at character {}",
164	                self.offset + 1
165	            )),
166	            None => Err("unexpected end of expression".into()),
167	        }
168	    }
169	
170	    fn parse_number(&mut self) -> Result<Expr, String> {
171	        let start = self.offset;
172	        let mut saw_digit = false;
173	        while self.peek().is_some_and(|ch| ch.is_ascii_digit()) {
174	            saw_digit = true;
175	            self.bump();
176	        }
177	        if self.peek() == Some('.') {
178	            self.bump();
179	            while self.peek().is_some_and(|ch| ch.is_ascii_digit()) {
180	                saw_digit = true;
181	                self.bump();
182	            }
183	        }
184	        if !saw_digit {
185	            return Err(format!("invalid number at character {}", start + 1));
186	        }
187	        if matches!(self.peek(), Some('e' | 'E')) {
188	            self.bump();
189	            if matches!(self.peek(), Some('+' | '-')) {
190	                self.bump();
191	            }
192	            let exponent_start = self.offset;
193	            while self.peek().is_some_and(|ch| ch.is_ascii_digit()) {
194	                self.bump();
195	            }
196	            if exponent_start == self.offset {
197	                return Err("invalid numeric exponent".into());
198	            }
199	        }
200	        let number = self.source[start..self.offset]
201	            .parse::<f64>()
202	            .map_err(|_| "invalid number".to_string())?;
203	        if !number.is_finite() {
204	            return Err("number is not finite".into());
205	        }
206	        Ok(Expr::Number(number))
207	    }
208	
209	    fn parse_name(&mut self) -> Result<Expr, String> {
210	        let start = self.offset;
211	        self.bump();
212	        while self.peek().is_some_and(is_identifier_continue) {
213	            self.bump();
214	        }
215	        let name = self.source[start..self.offset].to_ascii_lowercase();
216	        self.skip_space();
217	        if self.peek() != Some('(') {
218	            return Ok(Expr::Variable(name));
219	        }
220	        self.bump();
221	        let mut arguments = Vec::new();
222	        self.skip_space();
223	        if self.peek() != Some(')') {
224	            loop {
225	                arguments.push(self.parse_additive()?);
226	                self.skip_space();
227	                match self.peek() {
228	                    Some(',') => {
229	                        self.bump();
230	                    }
231	                    Some(')') => break,
232	                    _ => return Err(format!("expected ',' or ')' in {name}(...)")),
233	                }
234	            }
235	        }
236	        self.bump();
237	        let expected = match name.as_str() {
238	            "min" | "max" => 2,
239	            "sin" | "cos" | "tan" | "exp" | "ln" | "log" | "sqrt" | "abs" => 1,
240	            _ => return Err(format!("unknown function '{name}'")),
241	        };
242	        if arguments.len() != expected {
243	            return Err(format!("{name} expects {expected} argument(s)"));
244	        }
245	        Ok(Expr::Function(name, arguments))
246	    }
247	
248	    fn skip_space(&mut self) {
249	        while self.peek().is_some_and(char::is_whitespace) {
250	            self.bump();
251	        }
252	    }
253	
254	    fn peek(&self) -> Option<char> {
255	        self.source[self.offset..].chars().next()
256	    }
257	
258	    fn bump(&mut self) -> Option<char> {
259	        let ch = self.peek()?;
260	        self.offset += ch.len_utf8();
261	        Some(ch)
262	    }
263	}
264	
265	impl Expr {
266	    fn evaluate(&self, variables: &BTreeMap<String, f64>) -> Result<f64, String> {
267	        let value = match self {
268	            Self::Number(value) => *value,
269	            Self::Variable(name) if name == "pi" => std::f64::consts::PI,
270	            Self::Variable(name) if name == "e" => std::f64::consts::E,
271	            Self::Variable(name) => *variables
272	                .get(name)
273	                .ok_or_else(|| format!("unknown variable '{name}'"))?,
274	            Self::Unary('+', expression) => expression.evaluate(variables)?,
275	            Self::Unary('-', expression) => -expression.evaluate(variables)?,
276	            Self::Unary(operator, _) => return Err(format!("unknown unary operator '{operator}'")),
277	            Self::Binary(operator, left, right) => {
278	                let left = left.evaluate(variables)?;
279	                let right = right.evaluate(variables)?;
280	                match operator {
281	                    '+' => left + right,
282	                    '-' => left - right,
283	                    '*' => left * right,
284	                    '/' => left / right,
285	                    '^' => left.powf(right),
286	                    _ => return Err(format!("unknown operator '{operator}'")),
287	                }
288	            }
289	            Self::Function(name, arguments) => {
290	                let values = arguments
291	                    .iter()
292	                    .map(|argument| argument.evaluate(variables))
293	                    .collect::<Result<Vec<_>, _>>()?;
294	                match name.as_str() {
295	                    "sin" => values[0].sin(),
296	                    "cos" => values[0].cos(),
297	                    "tan" => values[0].tan(),
298	                    "exp" => values[0].exp(),
299	                    "ln" | "log" => values[0].ln(),
300	                    "sqrt" => values[0].sqrt(),
301	                    "abs" => values[0].abs(),
302	                    "min" => values[0].min(values[1]),
303	                    "max" => values[0].max(values[1]),
304	                    _ => return Err(format!("unknown function '{name}'")),
305	                }
306	            }
307	        };
308	        value
309	            .is_finite()
310	            .then_some(value)
311	            .ok_or_else(|| "expression produced a non-finite value".into())
312	    }
313	}
314	
315	fn is_identifier_start(ch: char) -> bool {
316	    ch.is_ascii_alphabetic() || ch == '_'
317	}
318	
319	fn is_identifier_continue(ch: char) -> bool {
320	    ch.is_ascii_alphanumeric() || ch == '_'
321	}
322	
323	fn valid_identifier(value: &str) -> bool {
324	    let mut chars = value.chars();
325	    chars.next().is_some_and(is_identifier_start) && chars.all(is_identifier_continue)
326	}
327	
328	impl PlotConfig {
329	    fn parse(props: &Value) -> Result<Self, String> {
330	        let parameters_json = props
331	            .get("parameters")
332	            .and_then(Value::as_array)
333	            .ok_or("parameters must be an array")?;
334	        if parameters_json.len() > MAX_PARAMETERS {
335	            return Err(format!("at most {MAX_PARAMETERS} parameters are supported"));
336	        }
337	
338	        let plot = props.get("plot").ok_or("plot is required")?;
339	        let x_json = plot.get("x").ok_or("plot.x is required")?;
340	        let x_id = text(x_json, "id").unwrap_or_else(|| "x".into());
341	        if x_id != x_id.to_ascii_lowercase()
342	            || !valid_identifier(&x_id)
343	            || matches!(x_id.as_str(), "pi" | "e")
344	        {
345	            return Err("plot.x.id must be a lowercase ASCII non-reserved variable name".into());
346	        }
347	        let x_min = finite_number(x_json, "min")?;
348	        let x_max = finite_number(x_json, "max")?;
349	        if x_min >= x_max {
350	            return Err("plot.x.min must be less than plot.x.max".into());
351	        }
352	        let samples = x_json
353	            .get("samples")
354	            .and_then(Value::as_u64)
355	            .unwrap_or(128)
356	            .clamp(2, MAX_SAMPLES as u64) as usize;
357	        let x = Axis {
358	            id: x_id.clone(),
359	            label: text(x_json, "label").unwrap_or_else(|| x_id.clone()),
360	            min: x_min,
361	            max: x_max,
362	            samples,
363	        };
364	
365	        let mut ids = BTreeSet::from([x_id, "pi".into(), "e".into()]);
366	        let mut parameters = Vec::with_capacity(parameters_json.len());
367	        for raw in parameters_json {
368	            let id = text(raw, "id").ok_or("every parameter requires an id")?;
369	            if id != id.to_ascii_lowercase() || !valid_identifier(&id) || !ids.insert(id.clone()) {
370	                return Err(format!(
371	                    "parameter id '{id}' must be lowercase ASCII, non-reserved, and unique"
372	                ));
373	            }
374	            let min = finite_number(raw, "min")?;
375	            let max = finite_number(raw, "max")?;
376	            if min >= max {
377	                return Err(format!("parameter '{id}' min must be less than max"));
378	            }
379	            let range = max - min;
380	            let step = raw
381	                .get("step")
382	                .and_then(Value::as_f64)
383	                .filter(|step| step.is_finite() && *step > 0.0)
384	                .unwrap_or(range / 100.0)
385	                .min(range);
386	            let value = raw
387	                .get("value")
388	                .and_then(Value::as_f64)
389	                .filter(|value| value.is_finite())
390	                .unwrap_or(min)
391	                .clamp(min, max);
392	            parameters.push(Parameter {
393	                label: text(raw, "label").unwrap_or_else(|| id.clone()),
394	                unit: text(raw, "unit").unwrap_or_default(),
395	                id,
396	                min,
397	                max,
398	                step,
399	                value,
400	            });
401	        }
402	
403	        let series_json = plot
404	            .get("series")
405	            .and_then(Value::as_array)
406	            .ok_or("plot.series must be an array")?;
407	        if series_json.is_empty() || series_json.len() > MAX_SERIES {
408	            return Err(format!(
409	                "plot.series must contain 1 to {MAX_SERIES} entries"
410	            ));
411	        }
412	        let mut series = Vec::with_capacity(series_json.len());
413	        for (index, raw) in series_json.iter().enumerate() {
414	            let source = text(raw, "expression")
415	                .ok_or_else(|| format!("series {} requires an expression", index + 1))?;
416	            series.push(Series {
417	                label: text(raw, "label").unwrap_or_else(|| format!("Series {}", index + 1)),
418	                expression: Parser::parse(&source)
419	                    .map_err(|error| format!("series {}: {error}", index + 1))?,
420	            });
421	        }
422	
423	        let metrics_json = props
424	            .get("metrics")
425	            .and_then(Value::as_array)
426	            .cloned()
427	            .unwrap_or_default();
428	        if metrics_json.len() > MAX_METRICS {
429	            return Err(format!("at most {MAX_METRICS} metrics are supported"));
430	        }
431	        let mut metrics = Vec::with_capacity(metrics_json.len());
432	        for (index, raw) in metrics_json.iter().enumerate() {
433	            let source = text(raw, "expression")
434	                .ok_or_else(|| format!("metric {} requires an expression", index + 1))?;
435	            metrics.push(Metric {
436	                label: text(raw, "label").unwrap_or_else(|| format!("Metric {}", index + 1)),
437	                expression: Parser::parse(&source)
438	                    .map_err(|error| format!("metric {}: {error}", index + 1))?,
439	                unit: text(raw, "unit").unwrap_or_default(),
440	                precision: raw
441	                    .get("precision")
442	                    .and_then(Value::as_u64)
443	                    .unwrap_or(2)
444	                    .min(6) as usize,
445	            });
446	        }
447	
448	        Ok(Self {
449	            title: text(props, "title").unwrap_or_default(),
450	            description: text(props, "description").unwrap_or_default(),
451	            parameters,
452	            x,
453	            y_label: text(plot, "y_label").unwrap_or_default(),
454	            series,
455	            metrics,
456	        })
457	    }
458	}
