575	#[component]
576	pub(super) fn InteractivePlotView(
577	    component_id: String,
578	    kind_props: Value,
579	    daemon: Daemon,
580	) -> impl IntoView {
581	    let config = PlotConfig::parse(&kind_props);
582	    let Ok(config) = config else {
583	        return view! {
584	            <div class="component-interactive-plot component-interactive-plot--error" role="status">
585	                <strong>"Interactive plot unavailable"</strong>
