590	    };
591	    let initial = config
592	        .parameters
593	        .iter()
594	        .map(|parameter| (parameter.id.clone(), parameter.value))
595	        .collect::<BTreeMap<_, _>>();
596	    let values = RwSignal::new(initial);
597	
598	    let graph_config = config.clone();
