628	                        let legend = series_labels.into_iter().enumerate().map(|(index, label)| view! {
629	                            <span class="interactive-plot__legend-item">
630	                                <i
631	                                    class=format!("interactive-plot__legend-swatch interactive-plot__legend-swatch--{}", index + 1)
632	                                    aria-hidden="true"
633	                                ></i>
634	                                <span>{label}</span>
635	                            </span>
636	                        }).collect::<Vec<_>>();
637	                        view! {
638	                            <div class="interactive-plot__y-label">{graph_config.y_label.clone()}</div>
639	                            <div class="interactive-plot__plot-area">
640	                                <span class="interactive-plot__y-max">{y_max}</span>
641	                                <svg viewBox="0 0 120 60" preserveAspectRatio="none" role="img" aria-label=plot_label>
642	                                    <line class="interactive-plot__grid" x1="0" y1="30" x2="120" y2="30"></line>
643	                                    {paths}
644	                                </svg>
645	                                <span class="interactive-plot__y-min">{y_min}</span>
646	                            </div>
647	                            <div class="interactive-plot__x-axis">
648	                                <span>{x_min}</span>
649	                                <span>{graph_config.x.label.clone()}</span>
650	                                <span>{x_max}</span>
651	                            </div>
652	                            <div class="interactive-plot__legend" aria-label="Plot series">{legend}</div>
653	                        }.into_any()
654	                    }
655	                    Err(error) => view! {
656	                        <div class="interactive-plot__error" role="status">{error}</div>
657	                    }.into_any(),
658	                }}
659	            </div>
660	
661	            {(!metric_config.metrics.is_empty()).then(|| view! {
662	                <div class="interactive-plot__metrics" aria-label="Derived metrics">
663	                    {move || {
664	                        let mut variables = values.get();
665	                        variables.insert(metric_config.x.id.clone(), metric_config.x.min);
666	                        metric_config.metrics.iter().map(|metric| {
667	                            let rendered = metric.expression.evaluate(&variables)
668	                                .map(|value| format!("{}{}", format_value(value, metric.precision), metric.unit))
669	                                .unwrap_or_else(|_| "Unavailable".into());
670	                            view! {
671	                                <div class="interactive-plot__metric">
672	                                    <span>{metric.label.clone()}</span>
673	                                    <strong>{rendered}</strong>
674	                                </div>
675	                            }
676	                        }).collect::<Vec<_>>()
677	                    }}
678	                </div>
679	            })}
680	
681	            {(!controls.is_empty()).then(|| view! {
682	                <div class="interactive-plot__controls" aria-label="Plot parameters">
683	                    {controls.into_iter().map(|parameter| {
684	                        let range_parameter = parameter.clone();
685	                        let number_parameter = parameter.clone();
