562	fn format_value(value: f64, precision: usize) -> String {
563	    let rendered = format!("{value:.precision$}");
564	    let Some((whole, fraction)) = rendered.split_once('.') else {
565	        return rendered;
566	    };
567	    let fraction = fraction.trim_end_matches('0');
568	    if fraction.is_empty() {
569	        whole.to_string()
570	    } else {
571	        format!("{whole}.{fraction}")
572	    }
573	}
