   131	/// Fold the daemon's global request/permission snapshots into a compact,
   132	/// truthful activity projection. Permissions replace their matching waiting
   133	/// request, terminal success/cancellation is omitted, and stale failure noise is
   134	/// bounded to the newest three authoritative errored requests.
   135	pub(crate) fn derive_attention_items(
   136	    requests: &[RequestSnapshot],
   137	    permissions: &[PermissionSnapshot],
   138	    sessions: &[IslandSession],
   139	) -> Vec<IslandAttentionItem> {
   140	    let permission_requests: HashSet<&str> = permissions
   141	        .iter()
   142	        .map(|permission| permission.request_id.as_str())
   143	        .collect();
   144	    let mut items = Vec::new();
   145	
   146	    for permission in permissions {
   147	        let (session_title, project) =
   148	            session_attention_metadata(sessions, permission.session_id.as_deref());
   149	        let tool = (!permission.tool.trim().is_empty()).then(|| permission.tool.trim().to_string());
   150	        let detail = if !permission.reason.trim().is_empty() {
   151	            bounded_detail(&permission.reason)
   152	        } else if let Some(tool) = tool.as_deref() {
   153	            format!("Review requested access for {tool}")
   154	        } else {
   155	            "Review requested access".to_string()
   156	        };
   157	        items.push(IslandAttentionItem {
   158	            id: format!("permission:{}", permission.permission_id),
   159	            request_id: permission.request_id.clone(),
   160	            permission_id: Some(permission.permission_id.clone()),
   161	            session_id: permission.session_id.clone(),
   162	            session_title,
   163	            project,
   164	            tool,
   165	            detail,
   166	            updated_at: permission.created_at.clone(),
   167	            state: IslandAttentionState::NeedsHuman,
   168	        });
   169	    }
   170	
   171	    let mut ordered_requests = requests.iter().collect::<Vec<_>>();
   172	    ordered_requests.sort_by(|a, b| {
   173	        request_updated_at(b)
   174	            .cmp(&request_updated_at(a))
   175	            .then_with(|| a.request_id.cmp(&b.request_id))
   176	    });
   177	    let mut failed_count = 0usize;
   178	    for request in ordered_requests {
   179	        if permission_requests.contains(request.request_id.as_str()) {
   180	            continue;
   181	        }
   182	        let state = match request.state {
   183	            RequestSnapshotState::Queued | RequestSnapshotState::Running => {
   184	                IslandAttentionState::Running
   185	            }
   186	            RequestSnapshotState::WaitingForPermission => IslandAttentionState::NeedsHuman,
   187	            RequestSnapshotState::Cancelling => IslandAttentionState::Cancelling,
   188	            RequestSnapshotState::Errored if failed_count < 3 => {
   189	                failed_count += 1;
   190	                IslandAttentionState::Failed
   191	            }
   192	            RequestSnapshotState::Errored
   193	            | RequestSnapshotState::Cancelled
   194	            | RequestSnapshotState::Completed => continue,
   195	        };
   196	        let (session_title, project) =
   197	            session_attention_metadata(sessions, request.session_id.as_deref());
   198	        let detail = request
   199	            .message
   200	            .as_deref()
   201	            .map(str::trim)
   202	            .filter(|message| !message.is_empty())
   203	            .map(bounded_detail)
   204	            .unwrap_or_else(|| state.label().to_string());
   205	        items.push(IslandAttentionItem {
   206	            id: format!("request:{}", request.request_id),
   207	            request_id: request.request_id.clone(),
   208	            permission_id: request.permission_id.clone(),
   209	            session_id: request.session_id.clone(),
   210	            session_title,
   211	            project,
   212	            tool: None,
   213	            detail,
   214	            updated_at: request_updated_at(request),
   215	            state,
   216	        });
   217	    }
   218	
   219	    items.sort_by(|a, b| {
   220	        a.state
   221	            .rank()
   222	            .cmp(&b.state.rank())
   223	            .then_with(|| b.updated_at.cmp(&a.updated_at))
   224	            .then_with(|| a.id.cmp(&b.id))
   225	    });
   226	    items
   227	}
