 797	/// Mint a fresh high-entropy per-turn permission `decision_token` (OCEAN-185).
 798	///
 799	/// Two v4 UUIDs (~244 bits of OS-seeded randomness), concatenated as hex. A
 800	/// client calls this once per turn, sends the value on the turn submission
 801	/// (`decision_token`), and replays the SAME value on any
 802	/// `/v1/permissions/{id}/decision` POST for that turn. The value travels only on
 803	/// the authenticated submit/decision request path the submitter holds — it is
 804	/// NEVER placed on the public `/v1/events` SSE — so an attacker who only sniffed
 805	/// the broadcast `permission_id` cannot forge an approval. Built on `uuid` (an
 806	/// existing dependency) to avoid pulling a fresh RNG crate; `Uuid::new_v4` draws
 807	/// from the OS CSPRNG via `getrandom`.
 808	pub fn mint_decision_token() -> String {
 809	    format!("{}{}", Uuid::new_v4().simple(), Uuid::new_v4().simple())
 810	}
 811	
 812	/// Constant-time equality for permission decision tokens (OCEAN-185).
 813	///
 814	/// Compares the `expected` token bound to a gated turn against the `presented`
 815	/// token on a decision POST without leaking length or content via timing. A
 816	/// `None` expected token means the turn was submitted WITHOUT binding (legacy
 817	/// client) — callers decide that policy separately; this only answers "do these
 818	/// two present tokens match". Returns `false` if either side is absent.
 819	pub fn decision_token_matches(expected: Option<&str>, presented: Option<&str>) -> bool {
 820	    let (Some(expected), Some(presented)) = (expected, presented) else {
 821	        return false;
 822	    };
 823	    let a = expected.as_bytes();
 824	    let b = presented.as_bytes();
 825	    // Fold the length difference into the accumulator so mismatched lengths
 826	    // still run a full constant-time-ish compare and never early-return.
 827	    let mut diff = (a.len() ^ b.len()) as u8;
 828	    let n = a.len().max(b.len());
 829	    for i in 0..n {
 830	        let x = a.get(i).copied().unwrap_or(0);
 831	        let y = b.get(i).copied().unwrap_or(0);
 832	        diff |= x ^ y;
 833	    }
 834	    diff == 0
 835	}
