  18	/// scan notices. Bound concurrent scans globally so abandoned/parallel queries
  19	/// cannot flood Tokio's blocking pool or multiply full-store I/O without limit.
  20	const MAX_CONCURRENT_HISTORY_SEARCHES: usize = 2;
  21	static HISTORY_SEARCH_SLOTS: LazyLock<Arc<Semaphore>> =
  22	    LazyLock::new(|| Arc::new(Semaphore::new(MAX_CONCURRENT_HISTORY_SEARCHES)));
