   646	            if hits.len() >= prune_at {
   647	                hits.sort_by(compare_history_hits);
   648	                hits.truncate(limit.saturating_mul(2).max(limit));
   649	            }
   650	        }
   651	    }
   652	
   653	    hits.sort_by(compare_history_hits);
   654	    hits.truncate(limit);
   655	    Ok(hits)
   656	}
