   658	fn compare_history_hits(a: &HistorySearchHit, b: &HistorySearchHit) -> std::cmp::Ordering {
   659	    match_rank(b.match_kind)
   660	        .cmp(&match_rank(a.match_kind))
   661	        .then_with(|| b.score.total_cmp(&a.score))
   662	        .then_with(|| {
   663	            b.timestamp_ms
   664	                .unwrap_or(0)
   665	                .cmp(&a.timestamp_ms.unwrap_or(0))
   666	        })
   667	        .then_with(|| a.hit_id.cmp(&b.hit_id))
   668	}
   669	
   670	fn match_rank(kind: HistoryMatchKind) -> u8 {
   671	    match kind {
   672	        HistoryMatchKind::Exact => 3,
   673	        HistoryMatchKind::Lexical => 2,
   674	        HistoryMatchKind::Fuzzy => 1,
   675	    }
   676	}
