  18	pub(super) struct RequestControl {
  19	    pub(super) status: RequestStatus,
  20	    pub(super) cancel: CancellationToken,
  21	    pub(super) handle: Option<JoinHandle<()>>,
  22	    /// Per-turn secret bound to the submitter (OCEAN-185, P0). Set from the
  23	    /// turn's `decision_token`; the gating policy copies it into every
  24	    /// `PermissionWaiter` this turn raises, and the decision POST must present
  25	    /// it. `None` = the turn was submitted without binding (a legacy/internal
  26	    /// turn). Never serialized onto the public `/v1/events` SSE. Held here so the
  27	    /// turn record owns the secret; the enforcement read is on the waiter.
