  98	pub(super) async fn register_running_request(
  99	    requests: &RequestRegistry,
 100	    req: &mut PromptRequest,
 101	    message: impl Into<String>,
 102	    state_value: RequestState,
 103	) -> (RequestId, CancellationToken) {
 104	    let request_id = req.request_id.unwrap_or_else(RequestId::new_v4);
 105	    req.request_id = Some(request_id);
 106	    let cancel = CancellationToken::new();
 107	    let now = Utc::now();
 108	
 109	    requests.write().await.insert(
 110	        request_id,
 111	        RequestControl {
 112	            status: RequestStatus {
 113	                request_id,
 114	                session_id: req.session_id,
 115	                state: state_value,
 116	                permission_id: None,
 117	                message: Some(message.into()),
 118	                started_at: Some(now),
 119	                updated_at: Some(now),
 120	                finished_at: None,
 121	            },
 122	            cancel: cancel.clone(),
 123	            handle: None,
 124	            // OCEAN-185: bind the turn's permission gate to the submitter. The
 125	            // token rides the request body (authenticated submit path) and is
 126	            // copied into every PermissionWaiter; it is NEVER emitted on the
 127	            // public /v1/events SSE.
 128	            decision_token: req.decision_token.clone(),
 129	        },
 130	    );
 131	
 132	    (request_id, cancel)
 133	}
