 146	pub(super) async fn cancel_permission_waiter(
 147	    permissions: &PermissionRegistry,
 148	    permission_id: PermissionId,
 149	    request_id: RequestId,
 150	) {
 151	    let waiter = {
 152	        let mut permissions = permissions.write().await;
 153	        permissions.remove(&permission_id)
 154	    };
 155	
 156	    if let Some(mut waiter) = waiter {
 157	        if waiter.status.request_id != request_id {
 158	            return;
 159	        }
 160	        if let Some(sender) = waiter.sender.take() {
 161	            let _ = sender.send(AgentPermissionDecision::Deny {
 162	                reason: "request cancelled while waiting for permission".into(),
 163	            });
 164	        }
 165	    }
 166	}
