 168	pub(super) async fn update_request_permission_result(
 169	    requests: &RequestRegistry,
 170	    request_id: RequestId,
 171	    permission_id: PermissionId,
 172	    decision: AgentPermissionDecision,
 173	) {
 174	    let mut requests = requests.write().await;
 175	    let Some(control) = requests.get_mut(&request_id) else {
 176	        return;
 177	    };
 178	
 179	    if control.status.state.is_terminal()
 180	        || matches!(control.status.state, RequestState::Cancelling)
 181	    {
 182	        return;
 183	    }
 184	
 185	    control.status.state = RequestState::Running;
 186	    control.status.permission_id = None;
 187	    control.status.message = Some(match decision {
 188	        AgentPermissionDecision::Allow => format!("permission {permission_id} allowed"),
 189	        AgentPermissionDecision::AllowSession => {
 190	            format!("permission {permission_id} allowed for session")
 191	        }
 192	        AgentPermissionDecision::Deny { ref reason } => {
 193	            format!("permission {permission_id} denied: {reason}")
 194	        }
 195	    });
 196	    control.status.updated_at = Some(Utc::now());
 197	}
