 199	pub(super) async fn update_request_finished(
 200	    requests: &RequestRegistry,
 201	    request_id: RequestId,
 202	    session_id: Option<SessionId>,
 203	    desired_state: RequestState,
 204	    message: String,
 205	) -> Option<RequestState> {
 206	    let mut requests = requests.write().await;
 207	    let control = requests.get_mut(&request_id)?;
 208	    let status = &mut control.status;
 209	
 210	    if matches!(
 211	        status.state,
 212	        RequestState::Cancelling | RequestState::Cancelled
 213	    ) {
 214	        status.session_id = session_id.or(status.session_id);
 215	        status.state = RequestState::Cancelled;
 216	        status.message = Some(
 217	            "cancel requested; runtime completed after cancellation request and output was ignored"
 218	                .into(),
 219	        );
 220	        status.updated_at = Some(Utc::now());
 221	        status.finished_at = Some(Utc::now());
 222	        let _ = control.handle.take();
 223	        return Some(RequestState::Cancelled);
 224	    }
 225	
 226	    if status.state.is_terminal() {
 227	        let _ = control.handle.take();
 228	        return Some(status.state);
 229	    }
 230	
 231	    status.session_id = session_id.or(status.session_id);
 232	    status.state = desired_state;
 233	    status.message = Some(message);
 234	    status.updated_at = Some(Utc::now());
 235	    status.finished_at = Some(Utc::now());
 236	    let _ = control.handle.take();
 237	    Some(desired_state)
 238	}
